=== submission_02.ino ===
   1| /*
   2|  * Lab 3: Hardware PWM
   3|  *
   4|  * Uses NRF_PWM1 to output 1 kHz @ 25% on D5 (P1.13).
   5|  *
   6|  * Calculations:
   7|  *   base clock      = 16 MHz
   8|  *   prescaler       = DIV_16  -> f_pwm = 1 MHz (1 us per count)
   9|  *   counter runs from 0 up to TOP-1 and then wraps, so
  10|  *   number of counts per period = 1000 -> TOP = 1000 - 1 = 999
  11|  *   duty            = 25% * 1000 counts = 250 counts
  12|  *
  13|  * Sequence word: [15] polarity (1 = high while counter < compare),
  14|  *                [14:0] compare value
  15|  */
  16| 
  17| #include <Arduino.h>
  18| 
  19| const uint32_t kPort      = 1;
  20| const uint32_t kPin       = 13;
  21| const uint16_t kCountsPer = 1000;
  22| const uint16_t kTop       = kCountsPer - 1;
  23| const uint16_t kCompare   = kCountsPer / 4;
  24| 
  25| uint16_t seqBuf[1] = { (uint16_t)(kCompare | (1u << 15)) };
  26| 
  27| void startPwm() {
  28|   NRF_PWM_Type *pwm = NRF_PWM1;
  29| 
  30|   pwm->PSEL.OUT[0] = (kPort << PWM_PSEL_OUT_PORT_Pos) | (kPin << PWM_PSEL_OUT_PIN_Pos);
  31|   pwm->ENABLE      = (PWM_ENABLE_ENABLE_Enabled << PWM_ENABLE_ENABLE_Pos);
  32|   pwm->MODE        = (PWM_MODE_UPDOWN_Up << PWM_MODE_UPDOWN_Pos);
  33|   pwm->PRESCALER   = (PWM_PRESCALER_PRESCALER_DIV_16 << PWM_PRESCALER_PRESCALER_Pos);
  34|   pwm->COUNTERTOP  = kTop;
  35|   pwm->LOOP        = 0;
  36|   pwm->DECODER     = (PWM_DECODER_LOAD_Common << PWM_DECODER_LOAD_Pos) |
  37|                      (PWM_DECODER_MODE_RefreshCount << PWM_DECODER_MODE_Pos);
  38| 
  39|   pwm->SEQ[0].PTR      = (uint32_t)&seqBuf[0];
  40|   pwm->SEQ[0].CNT      = 1;
  41|   pwm->SEQ[0].REFRESH  = 0;
  42|   pwm->SEQ[0].ENDDELAY = 0;
  43| 
  44|   pwm->TASKS_SEQSTART[0] = 1;
  45| }
  46| 
  47| void setup() {
  48|   startPwm();
  49| }
  50| 
  51| void loop() {
  52| }
</student_code>
